package com.gittexplorer.documentextractor.validation;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import com.gittexplorer.documentextractor.configuration.DocumentExtractionProperties;import com.gittexplorer.documentextractor.exception.InvalidUploadException;import com.gittexplorer.documentextractor.exception.UnsupportedDocumentTypeException;import com.gittexplorer.documentextractor.util.FileNameUtility;import java.util.Set;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockMultipartFile;import org.springframework.util.unit.DataSize;
class FileValidationServiceImplTest { private final DocumentExtractionProperties props=new DocumentExtractionProperties(); private final FileValidationServiceImpl service; FileValidationServiceImplTest(){props.setSupportedExtensions(Set.of("txt"));props.setSupportedMimeTypes(Set.of("text/plain"));props.setMaxFileSize(DataSize.ofBytes(5));props.setMaxRequestSize(DataSize.ofBytes(8));service=new FileValidationServiceImpl(props,new FileNameUtility());} @Test void rejectsEmptyUpload(){assertThatThrownBy(()->service.validate(new MockMultipartFile[]{new MockMultipartFile("files","a.txt","text/plain",new byte[0])})).isInstanceOf(InvalidUploadException.class);} @Test void rejectsOversizedTotal(){var a=new MockMultipartFile("files","a.txt","text/plain","12345".getBytes());var b=new MockMultipartFile("files","b.txt","text/plain","1234".getBytes());assertThatThrownBy(()->service.validate(new MockMultipartFile[]{a,b})).isInstanceOf(InvalidUploadException.class);} @Test void rejectsUnsupportedType(){assertThatThrownBy(()->service.validateSupported("a.exe","application/octet-stream")).isInstanceOf(UnsupportedDocumentTypeException.class);} }
